-- =====================================================================
-- PT Hartadinata Abadi Tbk (IDX: HRTA) - market data
--
-- share_snapshot : share counts at every date disclosed in the statements of changes in
--   equity of the filings (data/HRTA/xlsx, sheets 1410000 / 1410000PY), 2023-12-31 .. latest. shares_outstanding = common stock 460,526,240,000 / par Rp100
--   = 4,605,262,400; unchanged in every filing. basic_shares = weighted average used for
--   basic EPS (equal to issued shares: reported EPS = profit to parent / 4,605,262,400);
--   NULL for 2023-12-31 (no FY 2023 income statement in the filings).
--   treasury_shares = 0 (no treasury stock line in any balance sheet or equity
--   statement). diluted_shares and public_float are not disclosed in the filings (NULL).
--
-- price_daily : daily OHLCV of HRTA.JK in IDR from Yahoo Finance, saved as
--   data/HRTA/price/HRTA.JK_daily_yahoo.csv (649 trading days,
--   2024-01-02 .. 2026-09-30). Prices are not split-adjusted
--   because HRTA had no split in the range; adjusted_close is Yahoo's dividend-adjusted
--   close (cash dividends Rp15 ex 2024-05-06, Rp21 ex 2025-06-23, Rp40 ex 2026-06-12).
--   Removed from the raw feed: holiday placeholders without prices (2026-05-01,
--   2026-06-01, 2026-06-16, 2026-08-17, 2026-08-25), zero-volume holiday rows carrying
--   the previous close (2026-05-14, 2026-05-15, 2026-05-27, 2026-05-28) and the
--   unfinished intraday row of the download day.
--
-- Idempotent: upserts on (company_id, snapshot_date) / (company_id, trading_date).
-- =====================================================================

-- ---------------------------------------------------------------------
-- share_snapshot
-- ---------------------------------------------------------------------
INSERT INTO share_snapshot (
    company_id, snapshot_date, basic_shares, diluted_shares,
    shares_outstanding, public_float, treasury_shares)
SELECT c.company_id, v.snapshot_date, v.basic_shares, v.diluted_shares,
       v.shares_outstanding, v.public_float, v.treasury_shares
FROM company c
CROSS JOIN (VALUES
    (DATE '2023-12-31', NULL::NUMERIC, NULL::NUMERIC, 4605262400::NUMERIC, NULL::NUMERIC, 0::NUMERIC),  -- opening balance, FinancialStatement-2025-Tahunan-HRTA.xlsx sheet 1410000PY
    (DATE '2024-03-31', 4605262400, NULL, 4605262400, NULL, 0),  -- Q1 2024 period end, FinancialStatement-2025-I-HRTA.xlsx sheet 1410000PY
    (DATE '2024-06-30', 4605262400, NULL, 4605262400, NULL, 0),  -- H1 2024 period end, FinancialStatement-2025-II-HRTA.xlsx sheet 1410000PY
    (DATE '2024-09-30', 4605262400, NULL, 4605262400, NULL, 0),  -- 9M 2024 period end, FinancialStatement-2025-III-HRTA.xlsx sheet 1410000PY
    (DATE '2024-12-31', 4605262400, NULL, 4605262400, NULL, 0),  -- FY 2024 period end, FinancialStatement-2025-Tahunan-HRTA.xlsx sheet 1410000PY
    (DATE '2025-03-31', 4605262400, NULL, 4605262400, NULL, 0),  -- Q1 2025 period end, FinancialStatement-2025-I-HRTA.xlsx sheet 1410000
    (DATE '2025-06-30', 4605262400, NULL, 4605262400, NULL, 0),  -- H1 2025 period end, FinancialStatement-2025-II-HRTA.xlsx sheet 1410000
    (DATE '2025-09-30', 4605262400, NULL, 4605262400, NULL, 0),  -- 9M 2025 period end, FinancialStatement-2025-III-HRTA.xlsx sheet 1410000
    (DATE '2025-12-31', 4605262400, NULL, 4605262400, NULL, 0),  -- FY 2025 period end, FinancialStatement-2025-Tahunan-HRTA.xlsx sheet 1410000
    (DATE '2026-03-31', 4605262400, NULL, 4605262400, NULL, 0),  -- Q1 2026 period end, FinancialStatement-2026-I-HRTA.xlsx sheet 1410000
    (DATE '2026-06-30', 4605262400, NULL, 4605262400, NULL, 0)  -- H1 2026 period end, FinancialStatement-2026-II-HRTA.xlsx sheet 1410000
) AS v (snapshot_date, basic_shares, diluted_shares, shares_outstanding, public_float, treasury_shares)
WHERE c.ticker = 'HRTA' AND c.exchange = 'IDX'
ON CONFLICT ON CONSTRAINT uq_share_snapshot DO UPDATE SET
    basic_shares       = EXCLUDED.basic_shares,
    diluted_shares     = EXCLUDED.diluted_shares,
    shares_outstanding = EXCLUDED.shares_outstanding,
    public_float       = EXCLUDED.public_float,
    treasury_shares    = EXCLUDED.treasury_shares;

